    function respond(text) {
      const value = String(text || '').trim()
      if (value === '') return { mood: 'idle', line: 'line.idle' }
      const lower = value.toLowerCase()
      const has = (pattern) => pattern.test(lower)

      if (has(/谢谢|感谢|辛苦了|太棒了|厉害了|做得好|thanks|thank you|thx|good job|awesome|nice work/)) {
        if (has(/代码|bug|报错|跑通|编译|测试|code|build|test|works/)) return { mood: 'thanks', line: 'line.thanks.code' }
        if (has(/夸|厉害|棒|牛|beautiful|great|amazing|praise/)) return { mood: 'thanks', line: 'line.thanks.praise' }
        return { mood: 'thanks', line: 'line.thanks.default' }
      }

      if (has(/可爱|喜欢你|爱你|抱抱|贴贴|摸摸|love you|so cute|kawaii/)) {
        if (has(/可爱|cute|kawaii|好看/)) return { mood: 'shy', line: 'line.shy.praise' }
        return { mood: 'shy', line: 'line.shy.affection' }
      }

      if (has(/讨厌|笨蛋|傻瓜|垃圾|闭嘴|hate you|stupid|idiot|shut up/)) {
        if (has(/笨|傻|蠢|stupid|idiot/)) return { mood: 'pout', line: 'line.pout.insult' }
        return { mood: 'pout', line: 'line.pout.complain' }
      }

      if (has(/着急|急死|马上|赶紧|立刻|urgent|asap|right now|quickly/)) {
        if (has(/马上|赶紧|立刻|urgent|asap|right now|now/)) return { mood: 'surprised', line: 'line.surprised.urgent' }
        return { mood: 'surprised', line: 'line.surprised.exclaim' }
      }

      if (has(/难过|焦虑|累死|好累|心烦|压力|害怕|伤心|孤独|崩溃|sad|anxious|tired|stress|upset|depressed/)) {
        if (has(/累|tired|exhaust/)) return { mood: 'gentle', line: 'line.gentle.tired' }
        if (has(/焦虑|压力|害怕|anxious|stress|panic|nervous/)) return { mood: 'gentle', line: 'line.gentle.anxious' }
        if (has(/难过|伤心|孤独|崩溃|sad|upset|depressed/)) return { mood: 'gentle', line: 'line.gentle.sad' }
        return { mood: 'gentle', line: 'line.gentle.default' }
      }

      if (/^(hi|hello|hey)\b/i.test(value) || /^(你好|嗨|哈喽|在吗|早上好|晚上好|早安|晚安)/.test(value)) {
        const hasTask = has(/代码|编程|bug|报错|错误|函数|接口|api|组件|测试|编译|重构|部署|脚本|数据库|页面|网页|html|css|web|typescript|python|javascript|react|debug|error|fix|implement|build|refactor|deploy|写|画|故事|诗|文案|创意|设计|起名|取名|write|story|poem|design|creative|imagine|draw/)
        if (!hasTask) {
          if (has(/早安|早上好|^早(?:\s|$)|morning/)) return { mood: 'greeting', line: 'line.greeting.morning' }
          if (has(/晚安|晚上好|熬夜|夜深|night|late night/)) return { mood: 'greeting', line: 'line.greeting.night' }
          if (has(/又来了|回来了|我回来了|\bback\b|\bagain\b/)) return { mood: 'greeting', line: 'line.greeting.back' }
          return { mood: 'greeting', line: 'line.greeting.default' }
        }
      }

      if (has(/代码|编程|bug|报错|错误|函数|接口|api|组件|测试|编译|重构|部署|脚本|数据库|页面|网页|html|css|web|typescript|python|javascript|react|debug|error|fix|implement|build|refactor|deploy/)) {
        if (has(/报错|错误|异常|bug|error|exception|crash/)) return { mood: 'work', line: 'line.work.bug' }
        if (has(/测试|test|spec|用例/)) return { mood: 'work', line: 'line.work.test' }
        if (has(/部署|上线|deploy|release|rollback/)) return { mood: 'work', line: 'line.work.deploy' }
        if (has(/性能|卡顿|慢|优化|performance|latency|slow|memory/)) return { mood: 'work', line: 'line.work.performance' }
        if (has(/界面|样式|前端|页面|网页|html|css|web|布局|ui|frontend|layout/)) return { mood: 'work', line: 'line.work.frontend' }
        if (has(/编译|构建|打包|build|compile|bundle/)) return { mood: 'work', line: 'line.work.build' }
        return { mood: 'work', line: 'line.work.default' }
      }

      if (has(/为什么|怎么|如何|什么|是否|解释|区别|原理|分析|方案|思路|推导|证明|why|how|what|explain|compare|difference|analy[sz]e/)) {
        if (has(/为什么|why|原因|reason/)) return { mood: 'think', line: 'line.think.why' }
        if (has(/怎么|如何|how|步骤|step/)) return { mood: 'think', line: 'line.think.how' }
        if (has(/区别|对比|比较|compare|difference|vs/)) return { mood: 'think', line: 'line.think.compare' }
        if (has(/方案|计划|思路|plan|strategy|approach/)) return { mood: 'think', line: 'line.think.plan' }
        return { mood: 'think', line: 'line.think.default' }
      }

      if (has(/写|画|故事|诗|文案|创意|设计|起名|取名|write|story|poem|design|creative|imagine|draw/)) {
        if (has(/写|故事|诗|文案|write|story|poem|copy/)) return { mood: 'creative', line: 'line.creative.write' }
        if (has(/设计|画|draw|design|layout/)) return { mood: 'creative', line: 'line.creative.design' }
        if (has(/起名|取名|名字|name/)) return { mood: 'creative', line: 'line.creative.name' }
        return { mood: 'creative', line: 'line.creative.default' }
      }

      if (/[!！]/.test(value) && value.length > 4) return { mood: 'surprised', line: 'line.surprised.exclaim' }
      if (has(/[?？]/)) return { mood: 'curious', line: 'line.curious.question' }
      if (value.length <= 8) return { mood: 'curious', line: 'line.curious.short' }
      if (value.length > 120) return { mood: 'curious', line: 'line.curious.long' }
      return { mood: 'curious', line: 'line.curious.default' }
    }

    function nodeText(node) {
      const content = node && node.data && node.data.content
      if (!Array.isArray(content)) return ''
      return content
        .map((block) => (block && block.type === 'text' && typeof block.text === 'string' ? block.text : ''))
        .filter(Boolean)
        .join('\n')
        .trim()
    }

    function pickLatest(snapshot) {
      if (!snapshot || !Array.isArray(snapshot.order) || !snapshot.nodes || typeof snapshot.nodes.get !== 'function') {
        return undefined
      }
      for (let index = snapshot.order.length - 1; index >= 0; index -= 1) {
        const node = snapshot.nodes.get(snapshot.order[index])
        if (!node) continue
        if (node.visibility && node.visibility !== 'visible') continue
        if (node.kind === 'user' || node.kind === 'steering') return node
      }
      return undefined
    }

